def page(view,content):
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111b17"><meta name="description" content="Банная Мануфактура. Бани и загородные дома для вашего места силы. 39 моделей в коллекции."><title>Банная Мануфактура — искусство загородной жизни</title><link rel="stylesheet" href="style.css"></head><body data-page="{view}">{header}<main>{content}</main>{footer}{dialogs}<script src="catalog.js"></script><script src="app.js"></script></body></html>'''
